const promptRow = $('جلب البرومبت').item.json;
const lesson = $('جلب بيانات الدرس').item.json;
const sourcesRaw = $('جلب المصادر المعتمدة').all().map(i => i.json);

const sourcesText = sourcesRaw.map(s => {
  const sc = s.scientific_sources || {};
  return `- ${sc.source_code}: ${sc.organization} — ${sc.title} (${sc.source_url})`;
}).join('\n');

const userMessage = `lesson_code: ${lesson.lesson_code}
title_ar: ${lesson.title_ar}
content_type: ${lesson.content_type}
level: ${lesson.level}
professional_scope_note: ${lesson.professional_scope_note || 'لا يوجد'}
audiences: ممارسو البصريات، فاحصو النظر والعيادات، الأفراد والعائلات

approved_sources:
${sourcesText}`;

return [{ json: {
  prompt_uid: promptRow.prompt_uid,
  system: promptRow.prompt_text,
  user: userMessage,
  lesson_uid: 100001
} }];

const resp = $input.first().json;
const raw = (resp && resp.candidates && resp.candidates[0] && resp.candidates[0].content
  && resp.candidates[0].content.parts && resp.candidates[0].content.parts[0]
  && resp.candidates[0].content.parts[0].text) || '';
if (!raw) {
  const _err = JSON.stringify((resp && (resp.error || resp.promptFeedback)) || resp || {}).slice(0, 900);
  return [{ json: {
    lesson_uid: 100001,
    output_text: 'MODEL_ERROR: ' + _err,
    output_hash: 'model_error',
    model_used: 'gemini (no output)',
    parsed: { status: 'MODEL_ERROR', decision: 'MODEL_ERROR' },
    telegram_message: 'تعذّر تحليل ناتج النموذج: لا يوجد نص في رد النموذج (حجب أمان أو خطأ أو تجاوز حصة). التفاصيل: ' + _err
  } }];
}

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = { status: 'PARSE_ERROR' };
}

function simpleHash(str) {
  let h = 0;
  for (let i = 0; i < str.length; i++) {
    h = (Math.imul(31, h) + str.charCodeAt(i)) | 0;
  }
  return 'h' + Math.abs(h).toString(16) + '_' + str.length;
}

function clean(s) {
  return (s || '').toString().replace(/[<>&*_`\[\]~]/g, ' ');
}

const header = clean('توصيف الدرس B01 U01 C01 L01 (CONTENT DESC)');

let telegramMessage;
if (parsed.status === 'PASS') {
  const points = (parsed.key_points || []).map(k => '- ' + clean(k.point)).join('\n');
  telegramMessage = header + '\nالحالة PASS\n\n' + clean(parsed.description_text) + '\n\nالنقاط الأساسية\n' + points;
} else if (parsed.status === 'BLOCK') {
  const gaps = (parsed.evidence_gaps || []).map(g => typeof g === 'string' ? g : (g.gap || JSON.stringify(g))).map(clean).join('\n- ');
  telegramMessage = header + '\nالحالة BLOCK النموذج رفض إكمال المحتوى لنقص أدلة كافية\n\nسبب الرفض\n- ' + gaps;
} else {
  telegramMessage = header + '\nحدث خطأ في تحليل الناتج النص الخام\n' + clean(raw).slice(0, 1500);
}

return [{ json: {
  lesson_uid: $('تجميع الطلب').item.json.lesson_uid,
  output_text: raw,
  output_hash: simpleHash(raw),
  model_used: 'gpt-oss:120b-cloud (Ollama Cloud)',
  parsed,
  telegram_message: telegramMessage
} }];

