  return [{ json: {
    lesson_uid: 100001,
    output_text: 'MODEL_ERROR: ' + _err,
    output_hash: 'model_error',
    model_used: 'gemini (no output)',
    parsed: { status: 'MODEL_ERROR', decision: 'MODEL_ERROR' },
    telegram_message: 'تعذّر تحليل ناتج النموذج: لا يوجد نص في رد النموذج (حجب أمان أو خطأ أو تجاوز حصة). التفاصيل: ' + _err
  } }];
}

let parsed;
try { parsed = JSON.parse(raw); } catch (e) { parsed = { decision: 'PARSE_ERROR' }; }

function simpleHash(str) {
  let h = 0;
  for (let i = 0; i < str.length; i++) { h = (Math.imul(31, h) + str.charCodeAt(i)) | 0; }
  return 'h' + Math.abs(h).toString(16) + '_' + str.length;
}
function clean(s) { return (s || '').toString().replace(/[<>&*_`\[\]~]/g, ' '); }

const header = 'المراجعة العلمية للدرس B01 U01 C01 L01 (SCI REVIEW)';
let telegramMessage;
if (parsed.decision === 'PASS') {
  const claims = (parsed.claims || []).slice(0,6).map(c => `- ${clean(c.classification)} (${c.severity}): ${clean(c.claim).slice(0,100)}`).join('\n');
  telegramMessage = header + `\nالقرار PASS — مراجعة المراجع البشري لسه مطلوبة\n\nتصنيف الادعاءات (${(parsed.claims||[]).length} إجمالًا)\n` + claims + '\n\nملاحظة المراجع ' + clean(parsed.reviewer_note || '');
} else if (parsed.decision === 'BLOCK') {
  const issues = (parsed.blocking_issues || []).map(g => typeof g === 'string' ? g : JSON.stringify(g)).map(clean).join('\n- ');
  telegramMessage = header + '\nالقرار BLOCK\n\nالمشاكل المانعة\n- ' + issues;
} else {
  telegramMessage = header + '\nحدث خطأ\n' + clean(raw).slice(0, 1500);
}
if (telegramMessage.length > 3800) telegramMessage = telegramMessage.slice(0, 3800) + '\n[تم الاختصار]';

return [{ json: {
  lesson_uid: $('تجميع الطلب SCI').item.json.lesson_uid,
  output_text: raw,
  output_hash: simpleHash(raw),
  model_used: 'gpt-oss:120b-cloud (Ollama Cloud)',
  parsed,
  telegram_message: telegramMessage
} }];

const scene = $input.item.json;

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

const ANATOMY_TERMS = ['sclera','cornea','choroid','ciliary','iris','retina','rods','cones','optic nerve','lens','pupil','conjunctiva','vitreous','macula','fovea','photoreceptor','fibrous','vascular layer','layers of the eye'];

function isAnatomyScene(scene) {
  const text = (scene.narration || '').toLowerCase();
  return ANATOMY_TERMS.some((t) => text.includes(t));
}

async function fetchPollinationsImage(scene) {
  const prompt = 'professional medical scientific illustration, ' + scene.visual_prompt_en +
    ', clean flat vector art style, simple bold shapes, soft teal and navy blue color palette, minimalist, high quality medical textbook illustration, no text no letters no words';
  const url = 'https://image.pollinations.ai/prompt/' + encodeURIComponent(prompt) +
    '?width=1536&height=1024&nologo=true&seed=' + scene.scene_no;

  const maxTries = 3;
  const waitBetweenTries = 3000;
  let lastError = null;

  for (let attempt = 1; attempt <= maxTries; attempt++) {
    try {
      const buffer = await this.helpers.httpRequest({
        method: 'GET',
        url,
        encoding: 'arraybuffer',
        timeout: 45000,
      });
      const imgBuffer = Buffer.from(buffer);
      if (imgBuffer.length < 512) {
        throw new Error('استجابة صغيرة جدًا لتكون صورة صالحة (' + imgBuffer.length + ' بايت)');
      }
      return imgBuffer;
    } catch (err) {
      lastError = err;
      if (attempt < maxTries) {
        await sleep(waitBetweenTries);
      }
    }
  }
  throw new Error('فشل توليد صورة المشهد ' + scene.scene_no + ' بعد ' + maxTries + ' محاولات: ' + (lastError ? lastError.message : 'unknown error'));
}

function addNaturalPauses(text) {
  return String(text || '')
    .replace(/([.!؟?])\s+/g, '$1 <break time="0.3s"/> ');
}

async function fetchHeyGenSpeech(scene) {
  const bodyStr = JSON.stringify({
    text: addNaturalPauses(scene.narration),
    voice_id: 'e94bf61de2584daf96a6d82aa951caf5',
    speed: 1.05,
    language: 'ar',
  });

  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.heygen.com/v3/voices/speech',
    headers: {
      'X-Api-Key': 'sk_V2_hgu_kN6hHoI4T3x_wXWmrSzZ8z33PrcFp88oFCoICkvVafa5',
      'Content-Type': 'application/json',
    },
    body: bodyStr,
    json: false,
    timeout: 30000,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
  });

  if (response.statusCode < 200 || response.statusCode >= 300) {
    throw new Error('HeyGen HTTP ' + response.statusCode + ' body=' + JSON.stringify(response.body));
  }

  const data = typeof response.body === 'string' ? JSON.parse(response.body) : response.body;
  const inner = (data && data.data) || {};
  return { audioUrl: inner.audio_url || null, wordTimestamps: inner.word_timestamps || null };
}

const speech = await fetchHeyGenSpeech.call(this, scene);

const output = {
  scene_no: scene.scene_no,
  duration_seconds: scene.duration_seconds,
  narration: scene.narration,
  on_screen_text: scene.on_screen_text,
  source_codes: scene.source_codes,
  audio_url: speech.audioUrl,
};

if (isAnatomyScene(scene)) {
  output.use_custom_diagram = true;
  output.word_timestamps = speech.wordTimestamps;
  return { json: output };
}

const imageBuffer = await fetchPollinationsImage.call(this, scene);
const binaryData = await this.helpers.prepareBinaryData(imageBuffer, 'scene_' + scene.scene_no + '.jpg', 'image/jpeg');
output.image_base64 = imageBuffer.toString('base64');

return {
  json: output,
  binary: { data: binaryData },
};

const scene = $input.item.json;

const systemInstruction = "أنت خبير في كتابة أوصاف بصرية (prompts) لتوليد الصور بالذكاء الاصطناعي، متخصص في محتوى طبي تعليمي عن تشريح العين. مهمتك: حوّل الوصف العربي التالي إلى وصف بصري واحد بالإنجليزية، موجز ودقيق، مناسب لتوليد صورة برسم توضيحي طبي علمي احترافي (professional medical scientific illustration, flat vector style, soft teal and navy blue color palette, no text no letters no words). لا تترجم حرفياً فقط، بل أعد صياغته كوصف بصري فعّال لنموذج توليد الصور. أعد النتيجة بصيغة JSON فقط وبالضبط بهذا الشكل: {\"visual_prompt_en\": \"...\"}";

const userMessage = 'الوصف البصري بالعربية: ' + (scene.visual_prompt_en || '') + '\n\nسياق السرد (للفهم فقط، لا تترجمه ولا تدرجه في الناتج): ' + (scene.narration || '');

return { json: { ...scene, system: systemInstruction, user: userMessage } };

const resp = $input.item.json;
const original = $('بناء طلب ترجمة الوصف').item.json;
